package com.example

import com.example.ExamQuestionHelper.QSpec

internal object CivicsLiveExamElectionsBank2 {
  private const val T = "මැතිවරණ ක්‍රම, ඡන්ද බලය හා දේශපාලන පක්ෂ"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("ශ්‍රී ලංකාවේ ජනාධිපතිවරණයේදී ඡන්දදායකයන් සියලු දෙනා එක් මැතිවරණ කොට්ඨාසයක් ලෙස සලකන්නේ කෙසේද?", "මුළු රටම තනි මැතිවරණ කොට්ඨාසයක් ලෙස", "දිස්ත්‍රික්ක 22ක් වෙන වෙනම", "පළාත් 9ක් ලෙස", "මන්ත්‍රී ආසන 160ක් ලෙස", "ජනාධිපතිවරණයේදී මුළු ශ්‍රී ලංකාවම එක් ඡන්ද කොට්ඨාසයක් ලෙස සලකා ජාතික ඡන්ද එකතුව ගණනය කෙරේ."),
    q("ජනාධිපතිවරණයකදී කිසිදු අපේක්ෂකයෙකුට පළමු වටයේදී 50% ඉක්මවූ වලංගු ඡන්ද නොලැබුණහොත් ක්‍රියාත්මක වන ක්‍රමය කුමක්ද?", "දෙවන හා තෙවන මනාප ගණන් කිරීම", "වැඩිම ඡන්ද ඇති අය ජයග්‍රාහකයා කිරීම", "පාර්ලිමේන්තුවෙන් ජනාධිපති තේරීම", "දින 30කින් නව මැතිවරණයක් තැබීම", "ප්‍රමුඛ අපේක්ෂකයන් දෙදෙනා හැර සෙසු අපේක්ෂකයන් ඉවත් කර ඔවුන්ගේ දෙවන හා තෙවන මනාප එකතු කෙරේ."),
    q("ශ්‍රී ලංකාවේ ජනාධිපතිවරණයකදී ඡන්දදායකයෙකුට අපේක්ෂකයන් තිදෙනෙකු සිටින විට ලකුණු කළ හැකි මනාප සංඛ්‍යාව කීයද?", "1, 2 සහ 3 ලෙස මනාප තුනක්", "මනාප පහක්", "මනාප දහයක්", "පළමු කතිරය පමණක්", "අපේක්ෂකයන් තිදෙනෙකුට වඩා සිටින විට 1, 2, 3 ලෙස මනාප තුනක් සලකුණු කිරීමේ අයිතිය ඡන්දදායකයාට ඇත."),
    q("ජනාධිපතිවරණයකදී අපේක්ෂකයන් දෙදෙනෙකු පමණක් තරග කරන්නේ නම් ඡන්දදායකයෙකු මනාප සලකුණු කරන්නේ කෙසේද?", "පළමු මනාපය (1) හෝ කතිරය පමණක්", "මනාප 1, 2 සහ 3 තුනම", "දෙවන මනාපය පමණක්", "පක්ෂ ලැයිස්තුවට අංක යෙදීමෙන්", "අපේක්ෂකයන් දෙදෙනෙකු පමණක් සිටින විට එක් අයෙකුට 1 හෝ කතිරය ලකුණු කරන අතර දෙවන මනාප අවශ්‍ය නොවේ."),
    q("19 වන ව්‍යවස්ථා සංශෝධනය අනුව ශ්‍රී ලංකාවේ ජනාධිපතිවරණයකට ඉදිරිපත් විය හැකි අවම වයස් සීමාව කුමක්ද?", "අවුරුදු 35", "අවුරුදු 30", "අවුරුදු 25", "අවුරුදු 40", "19 වන සංශෝධනය මඟින් ජනාධිපති ධුර අපේක්ෂක අවම වයස් සීමාව අවුරුදු 30 සිට 35 දක්වා ඉහළ නැංවීය."),
    q("වර්තමාන ව්‍යවස්ථාව අනුව පුද්ගලයෙකුට ශ්‍රී ලංකාවේ විධායක ජනාධිපති ධුරය දැරිය හැකි උපරිම වාර ගණන කීයද?", "දෙවරක්", "එක් වරක්", "තිවරක්", "සීමාවක් නැත", "19 වන ව්‍යවස්ථා සංශෝධනයෙන් ජනාධිපති ධුරය දැරිය හැකි උපරිම සීමාව වාර දෙකක් ලෙස යළි ස්ථාපිත කෙරිණි."),
    q("ශ්‍රී ලංකාවේ පළමු විධායක ජනාධිපතිවරණය පවත්වන ලද්දේ කුමන වර්ෂයේදීද?", "1982", "1978", "1988", "1994", "ජේ.ආර්. ජයවර්ධන සහ හෙක්ටර් කොබ්බෑකඩුව තරග කළ පළමු ජනාධිපතිවරණය 1982 ඔක්තෝබර් 20 පැවැත්වුණි."),
    q("සරල බහුතර කොට්ඨාස ක්‍රමය සහ සමානුපාතික ලැයිස්තු ක්‍රමය යන දෙකම ඒකාබද්ධ කර සැකසූ මැතිවරණ ක්‍රමය කුමක්ද?", "මිශ්‍ර මැතිවරණ ක්‍රමය", "සංවෘත ලැයිස්තු ක්‍රමය", "ඒකපාක්ෂික ක්‍රමය", "බහු මන්ත්‍රී කේවල ක්‍රමය", "කේවල ආසන මට්ටමින් පත්වන සභිකයන් හා සමානුපාතික ලැයිස්තුවෙන් පත්වන සභිකයන් එක්කළ ක්‍රමය මිශ්‍ර ක්‍රමයයි."),
    q("වර්තමාන ශ්‍රී ලංකාවේ පළාත් පාලන ආයතන (මහ නගර, නගර හා ප්‍රාදේශීය සභා) මැතිවරණවල භාවිත වන ක්‍රමය කුමක්ද?", "60% කොට්ඨාස හා 40% සමානුපාතික මිශ්‍ර ක්‍රමය", "100% සමානුපාතික ක්‍රමය", "100% කේවල ක්‍රමය", "තනි මාරු ඡන්ද ක්‍රමය", "පළාත් පාලන සභිකයන් 60%ක් කොට්ඨාස මට්ටමින්ද ඉතිරි 40% පක්ෂ සමානුපාතික ලැයිස්තුවෙන්ද තෝරා ගැනේ."),
    q("මිශ්‍ර සමානුපාතික නියෝජන ක්‍රමය (MMP) සාර්ථකව ක්‍රියාත්මක වන ප්‍රමුඛ යුරෝපීය රට කුමක්ද?", "ජර්මනිය", "ප්‍රංශය", "එක්සත් රාජධානිය", "ග්‍රීසිය", "ජර්මනියේ බුන්ඩෙස්ටැග් පාර්ලිමේන්තුව සඳහා ඡන්දදායකයන්ට ඡන්ද දෙකක් සහිත මිශ්‍ර සමානුපාතික ක්‍රමය භාවිත වේ."),
    q("ජාතික වැදගත්කමක් ඇති පනත් කෙටුම්පතක් හෝ ව්‍යවස්ථා සංශෝධනයක් සෘජුවම මහජන අනුමැතියට යොමු කිරීම කුමක්ද?", "ජනමත විචාරණය", "මහ මැතිවරණය", "අතුරු මැතිවරණය", "ප්‍රාථමික මැතිවරණය", "ව්‍යවස්ථාදායකයේ තීරණයකට අමතරව සෘජුවම ජනතාවගේ 'ඔව්/නැත' කැමැත්ත විමසීම ජනමත විචාරණයයි."),
    q("1978 ව්‍යවස්ථාවේ 83 වන වගන්තිය අනුව සඳහන් වගන්ති සංශෝධනය කිරීමට 2/3 බහුතරයට අමතරව කුමක් අවශ්‍ය වේද?", "ජනමත විචාරණයකින් අනුමැතිය", "පළාත් ආණ්ඩුකාරවරුන්ගේ අනුමැතිය", "මහ නගර සභාවල අනුමැතිය", "එක්සත් ජාතීන්ගේ අනුමැතිය", "රටේ ස්වෛරීභාවය, ජාතික ධජය, බුද්ධාගම, මූලික අයිතිවාසිකම් වැනි මූලික වගන්ති සඳහා ජනමත විචාරණයක් අනිවාර්ය වේ."),
    q("ශ්‍රී ලංකා ඉතිහාසයේ මේ දක්වා පැවැති එකම ජනමත විචාරණය පවත්වන ලද්දේ කුමන වර්ෂයේදීද?", "1982", "1972", "1987", "2015", "1977 පාර්ලිමේන්තුවේ නිල කාලය තවත් වසර හයකින් දීර්ඝ කර ගැනීමට 1982 දෙසැම්බර් 22 ජනමත විචාරණය පැවැත්වුණි."),
    q("1982 ජනමත විචාරණයේදී පාර්ලිමේන්තු කාලය දීර්ඝ කිරීමට පක්ෂව හා විපක්ෂව භාවිත කළ සංකේත යුගලය කුමක්ද?", "ලාම්පුව සහ කළගෙඩිය", "අලියා සහ අත", "පුටුව සහ සීනුව", "බුලත් කොළය සහ හංසයා", "යෝජනාවට පක්ෂ 'ඔව්' පාර්ශ්වය ලාම්පුව සලකුණෙන්ද විපක්ෂ 'නැත' පාර්ශ්වය කළගෙඩිය සලකුණෙන්ද තරග කළහ."),
    q("ශ්‍රී ලංකාවේ ජනමත විචාරණයකදී මුළු ලියාපදිංචි ඡන්ද සංඛ්‍යාවෙන් 2/3කට අඩුවෙන් ඡන්දය දුන් විට යෝජනාව සම්මත වීමට නම් කුමක් සිදුවිය යුතුද?", "ලියාපදිංචි මුළු ඡන්දදායකයන්ගෙන් 1/3කට වඩා පක්ෂව ඡන්දය දීම", "ලැබුණු ඡන්දවලින් 25%ක් ලබාගැනීම", "පළාත් පහක ජයග්‍රහණය කිරීම", "ජනාධිපතිවරයා අත්සන් තැබීම", "ප්‍රකාශිත ඡන්ද 2/3 නොඉක්මවන විට බහුතරය මෙන්ම මුළු ලියාපදිංචි ඡන්දවලින් 1/3ක අවමයද අවශ්‍ය වේ."),
    q("ශ්‍රී ලංකාවේ සියලු මැතිවරණ හා ජනමත විචාරණ පැවැත්වීමේ සහ අධීක්ෂණයේ වගකීම හිමි ස්වාධීන ආයතනය කුමක්ද?", "මැතිවරණ කොමිෂන් සභාව", "රාජ්‍ය සේවා කොමිෂන් සභාව", "අධිකරණ සේවා කොමිෂන් සභාව", "පළාත් පාලන කොමිෂන් සභාව", "ව්‍යවස්ථාවේ XIV ආ පරිච්ඡේදය යටතේ මැතිවරණ කොමිෂන් සභාව ස්ථාපිත කර ඇත."),
    q("21 වන ව්‍යවස්ථා සංශෝධනය අනුව ශ්‍රී ලංකා මැතිවරණ කොමිෂන් සභාවේ සාමාජික සංඛ්‍යාව කීයද?", "5", "3", "7", "9", "20 වන සංශෝධනයෙන් තිදෙනෙකුට සීමා කළ කොමිසම 21 වන සංශෝධනයෙන් යළි සාමාජිකයන් 5 දක්වා වැඩි කෙරිණි."),
    q("මැතිවරණ කොමිෂන් සභාවේ සභාපතිවරයා හා සාමාජිකයන් පත් කරනු ලබන්නේ කවුරුන් විසින්ද?", "ආණ්ඩුක්‍රම ව්‍යවස්ථා සභාවේ නිර්දේශ මත ජනාධිපතිවරයා", "අග්‍රාමාත්‍යවරයාගේ තනි තීරණයෙන්", "විපක්ෂ නායකවරයා විසින්", "ශ්‍රේෂ්ඨාධිකරණ විනිසුරුවරුන් විසින්", "ආණ්ඩුක්‍රම ව්‍යවස්ථා සභාවේ අනුමැතිය හා නිර්දේශය මත ජනාධිපතිවරයා කොමිෂන් සභාව පත් කරයි."),
    q("ශ්‍රී ලංකාවේ දිස්ත්‍රික් මට්ටමින් මැතිවරණ පැවැත්වීමේ 'තේරීම් භාර නිලධාරියා' (Returning Officer) ලෙස කටයුතු කරන්නේ කවුද?", "දිස්ත්‍රික් ලේකම්වරයා", "මහ නගරාධිපතිවරයා", "දිස්ත්‍රික් විනිසුරුවරයා", "ජ්‍යෙෂ්ඨ පොලිස් අධිකාරීවරයා", "සෑම මැතිවරණ දිස්ත්‍රික්කයකම පරිපාලන ප්‍රධානියා වන දිස්ත්‍රික් ලේකම්වරයා තේරීම් භාර නිලධාරියා වේ."),
    q("මැතිවරණ දිනයේදී එක් ඡන්ද මධ්‍යස්ථානයක සම්පූර්ණ කටයුතු පාලනය කරන ප්‍රධාන නිලධාරියා කවුද?", "ඡන්ද ස්ථානාධිපති", "ග්‍රාම නිලධාරී", "ඡන්ද පොළ නියෝජිතයා", "පළාත් කොමසාරිස්", "මැතිවරණ කොමිසම විසින් පත් කරන ජ්‍යෙෂ්ඨ ඡන්ද ස්ථානාධිපතිවරයා එම ඡන්ද පොළේ ප්‍රධානියා වේ."),
    q("මැතිවරණ රාජකාරිවල නිරත රජයේ නිලධාරීන්, පොලිසිය හා ත්‍රිවිධ හමුදා සාමාජිකයන් ඡන්දය දෙන ක්‍රමය කුමක්ද?", "තැපැල් ඡන්ද ක්‍රමය", "අන්තර්ජාල ඡන්ද ක්‍රමය", "නියෝජිත ඡන්ද ක්‍රමය", "විදේශීය ඡන්ද ක්‍රමය", "මැතිවරණ දිනයේ රාජකාරියේ යෙදෙන රාජ්‍ය සේවකයන්ට කලින් දිනවලදී තැපැල් ඡන්දය භාවිත කිරීමට අවසර ලැබේ."),
    q("මැතිවරණ දිනයට පෙර රැස්වීම්, පෙළපාලි හා ප්‍රචාරණ කටයුතු තහනම් කරන පැය 48ක කාලසීමාව කුමන නමින් හැඳින්වේද?", "නිහඬ කාලසීමාව", "හදිසි නීති කාලසීමාව", "අතුරු කාලසීමාව", "ඇඳිරි නීති කාලසීමාව", "ඡන්දදායකයන්ට සාමකාමීව හා නිදහසේ තීරණයක් ගැනීමට මැතිවරණයට පෙර පැය 48ක් නිහඬ කාලය ලෙස පනවා ඇත."),
    q("මැතිවරණ කොට්ඨාස සීමා වෙනස් කිරීම හෝ අලුතින් බෙදා වෙන් කිරීම සිදුකරන ආයතනය කුමක්ද?", "සීමා නිර්ණ කොමිෂන් සභාව", "රාජ්‍ය සේවා කොමිෂන් සභාව", "විගණන සේවා කොමිසම", "අල්ලස් හෝ දූෂණ කොමිසම", "ජනගහන වෙනස්වීම් හා භූගෝලීය සාධක සලකා කොට්ඨාස මායිම් නිර්ණය කිරීම සීමා නිර්ණ කොමිසමේ කාර්යයයි."),
    q("ඡන්ද පොළ තුළ සිදුවන කටයුතු සාධාරණදැයි පරීක්ෂා කිරීමට පක්ෂ මඟින් පත් කර එවන නියෝජිතයන් හඳුන්වන්නේ කෙසේද?", "ඡන්ද පොළ නියෝජිතයන්", "ගණන් කිරීමේ නිලධාරීන්", "නිරීක්ෂණ කොමසාරිස්වරුන්", "නීතිපති නියෝජිතයන්", "සෑම තරගකාරී පක්ෂයකටම හෝ අපේක්ෂකයෙකුටම ඡන්ද පොළ තුළ නියෝජිතයන් දෙදෙනෙකු දක්වා රැඳවිය හැක."),
    q("මැතිවරණ ප්‍රචණ්ඩ ක්‍රියා හා නීති උල්ලංඝනය කිරීම් නිරීක්ෂණය කරන ශ්‍රී ලංකාවේ සිවිල් සංවිධාන දෙකක් කවරේද?", "පැෆරල් (PAFFREL) සහ කැෆේ (CMEV / CaFFE)", "යුනෙස්කෝ සහ යුනිසෙෆ්", "අන්තර්ජාතික මූල්‍ය අරමුදල සහ ලෝක බැංකුව", "සාර්ක් සහ බිම්ස්ටෙක්", "PAFFREL, CMEV සහ CaFFE යනු ශ්‍රී ලංකාවේ ස්වාධීන මැතිවරණ නිරීක්ෂණ සිවිල් සංවිධාන වේ."),
    q("ශ්‍රී ලංකාවේ පළාත් සභා සහ පාර්ලිමේන්තු ආසන ගණන අතර හෝ දිස්ත්‍රික්ක නාමයෝජනා පිළිබඳ ගැටලු විභාග කරන අධිකරණය කුමක්ද?", "අභියාචනාධිකරණය හා ශ්‍රේෂ්ඨාධිකරණය", "කම්කරු විනිශ්චය සභාව", "සමථ මණ්ඩලය", "දිසා අධිකරණය", "ඡන්ද පෙත්සම් සහ මැතිවරණ නීති ගැටලු ඉහළ අධිකරණ වන අභියාචනාධිකරණය හා ශ්‍රේෂ්ඨාධිකරණය මඟින් විභාග කෙරේ."),
    q("පොදු මූලධර්ම පදනම් කරගෙන නීත්‍යානුකූල මැතිවරණ මඟින් රාජ්‍ය බලය ලබාගැනීමට ක්‍රියා කරන පුරවැසි සංවිධානය කුමක්ද?", "දේශපාලන පක්ෂය", "වෘත්තීය සමිතිය", "සමුපකාර සමිතිය", "ව්‍යාපාරික මණ්ඩලය", "රාජ්‍ය බලය අත්පත් කර ගැනීමේ අරමුණින් සංවිධානය වූ දේශපාලන කණ්ඩායම දේශපාලන පක්ෂයක් නම් වේ."),
    q("රටේ පාලනය සඳහා නීත්‍යානුකූලව ක්‍රියාත්මක වීමට ඉඩ ඇත්තේ එක් දේශපාලන පක්ෂයකට පමණක් නම් එය කුමන පක්ෂ ක්‍රමයද?", "ඒකපාක්ෂික ක්‍රමය", "ද්විපාක්ෂික ක්‍රමය", "බහුපාක්ෂික ක්‍රමය", "සභාග පක්ෂ ක්‍රමය", "මහජන චීන සමූහාණ්ඩුව වැනි රටවල ක්‍රියාත්මක වන්නේ එක් ප්‍රධාන පක්ෂයක් පාලනය කරන ඒකපාක්ෂික ක්‍රමයයි."),
    q("ප්‍රධාන දේශපාලන පක්ෂ දෙකක් අතර පාලන බලය මාරුවෙන් මාරුවට හුවමාරු වන රටවල් යුගලයක් කවරේද?", "ඇමරිකා එක්සත් ජනපදය සහ එක්සත් රාජධානිය", "චීනය සහ උතුරු කොරියාව", "ශ්‍රී ලංකාව සහ ඉන්දියාව", "බෙල්ජියම සහ ඉතාලිය", "ඇමරිකාවේ (ඩිමොක්‍රටික්/රිපබ්ලිකන්) සහ බ්‍රිතාන්‍යයේ (කන්සර්වේටිව්/කම්කරු) ද්විපාක්ෂික ක්‍රමය ප්‍රකටය."),
    q("ශ්‍රී ලංකාවේ සහ ඉන්දියාවේ ක්‍රියාත්මක වන දේශපාලන පක්ෂ ක්‍රමය කුමක්ද?", "බහුපාක්ෂික ක්‍රමය", "ඒකපාක්ෂික ක්‍රමය", "නිර්පාක්ෂික ක්‍රමය", "රාජකීය පක්ෂ ක්‍රමය", "විවිධ මතවාද නියෝජනය කරන පක්ෂ රැසක් නිදහසේ මැතිවරණවලට තරග කරන බැවින් එය බහුපාක්ෂික ක්‍රමයකි."),
    q("මැතිවරණයකට පෙර දේශපාලන පක්ෂයක් තම ඉදිරි වැඩපිළිවෙළ සහ ප්‍රතිඥා ජනතාවට ඉදිරිපත් කරන ලේඛනය කුමක්ද?", "මැතිවරණ ප්‍රතිපත්ති ප්‍රකාශනය", "ගැසට් නිවේදනය", "විගණකාධිපති වාර්තාව", "චක්‍රලේඛය", "පක්ෂයේ ඉදිරි ආර්ථික හා සමාජ ප්‍රතිපත්ති ජනතාවට හඳුන්වා දෙන ලේඛනය ප්‍රතිපත්ති ප්‍රකාශනය (Manifesto) වේ."),
    q("පාර්ලිමේන්තුවේ ආණ්ඩු පක්ෂයේ ප්‍රතිපත්ති විවේචනය කරමින් විකල්ප රජයක් සඳහා සූදානම්ව සිටින කණ්ඩායම කුමක්ද?", "විපක්ෂය", "කැබිනට් මණ්ඩලය", "රාජ්‍ය සේවා කොමිසම", "ශ්‍රේෂ්ඨාධිකරණය", "ආණ්ඩුවේ වැරදි පෙන්වා දී ජනතා අයිතීන් රැකීම ප්‍රජාතන්ත්‍රවාදී විපක්ෂයේ ප්‍රධාන කාර්යභාරයයි."),
    q("එක්සත් රාජධානිය වැනි පාර්ලිමේන්තු ක්‍රමවල විපක්ෂය විසින් සෑම අමාත්‍යවරයෙකුගේම කටයුතු අධීක්ෂණයට පත් කරන කණ්ඩායම කුමක්ද?", "ඡායා කැබිනට්ටුව", "ආණ්ඩුකාර මණ්ඩලය", "උත්තර මන්ත්‍රී මණ්ඩලය", "සමථ කමිටුව", "අමාත්‍යවරුන්ට සමාන්තරව විපක්ෂ නායක ප්‍රමුඛව පිහිටුවන විකල්ප අමාත්‍ය කණ්ඩායම ඡායා කැබිනට්ටුවයි."),
    q("ශ්‍රී ලංකාවේ බිහි වූ ප්‍රථම විධිමත් දේශපාලන පක්ෂය ලෙස සැලකෙන්නේ කුමක්ද?", "ලංකා සමසමාජ පක්ෂය", "එක්සත් ජාතික පක්ෂය", "ශ්‍රී ලංකා නිදහස් පක්ෂය", "ජනතා විමුක්ති පෙරමුණ", "1935 දෙසැම්බර් 18 දින ආචාර්ය ඇන්.ඇම්. පෙරේරා ඇතුළු පිරිස විසින් ලංකා සමසමාජ පක්ෂය පිහිටුවන ලදී."),
    q("1946 දී ඩී.ඇස්. සේනානායක මහතාගේ නායකත්වයෙන් පිහිටුවන ලද ප්‍රධාන දේශපාලන පක්ෂය කුමක්ද?", "එක්සත් ජාතික පක්ෂය", "ශ්‍රී ලංකා නිදහස් පක්ෂය", "ලංකා කොමියුනිස්ට් පක්ෂය", "මහජන එක්සත් පෙරමුණ", "ලංකා ජාතික සංගමය ඇතුළු සංවිධාන එක්කර 1946 සැප්තැම්බර් 6 දින එක්සත් ජාතික පක්ෂය පිහිටුවන ලදී."),
    q("1951 දී ඇස්.ඩබ්ලිව්.ආර්.ඩී. බණ්ඩාරනායක මහතා විසින් ආරම්භ කරන ලද දේශපාලන පක්ෂය කුමක්ද?", "ශ්‍රී ලංකා නිදහස් පක්ෂය", "ලංකා සමසමාජ පක්ෂය", "ඉලංකෙයි තමිල් අරසු කච්චි", "ලංකා කම්කරු කොංග්‍රසය", "1951 සැප්තැම්බර් 2 දින බණ්ඩාරනායක මහතාගේ මූලිකත්වයෙන් ශ්‍රී ලංකා නිදහස් පක්ෂය පිහිටුවනු ලැබීය."),
    q("වෘත්තීය සමිතියක් හෝ බලපෑම් කණ්ඩායමක් (Pressure Group) දේශපාලන පක්ෂයකින් වෙනස් වන ප්‍රධාන ලක්ෂණය කුමක්ද?", "බලපෑම් කණ්ඩායම් ආණ්ඩු බලය ලබාගැනීමට තරග නොකරයි", "බලපෑම් කණ්ඩායම්වලට සාමාජිකයන් නැත", "දේශපාලන පක්ෂ මැතිවරණවලට තරග නොකරයි", "බලපෑම් කණ්ඩායම් නීතියෙන් තහනම් කර ඇත", "දේශපාලන පක්ෂ මැතිවරණවලින් ආණ්ඩු බලය ගැනීමට තරග කරන අතර බලපෑම් කණ්ඩායම් ප්‍රතිපත්තිවලට බලපෑම් කරයි."),
    q("මැතිවරණයකින් පසු කිසිදු තනි පක්ෂයකට පාර්ලිමේන්තු බහුතරය නොලැබුණු විට පක්ෂ කිහිපයක් එක්වී පිහිටුවන ආණ්ඩුව කුමක්ද?", "සභාග ආණ්ඩුව", "ඒකපාක්ෂික ආණ්ඩුව", "භාරකාර රජය", "ජනරජ සභාව", "පක්ෂ කිහිපයක එකඟතාවයෙන් බහුතර බලය ගොඩනඟා පිහිටුවන ආණ්ඩුව සභාග ආණ්ඩුව (Coalition Government) වේ."),
    q("දේශපාලන පක්ෂ විසින් මහජනතාවට දේශපාලන දැනුම හා අවබෝධය ලබාදීමේ කාර්යය හඳුන්වන්නේ කුමන නමින්ද?", "දේශපාලන සමාජානුයෝජනය", "පරිපාලන මධ්‍යගතකරණය", "රාජ්‍ය විමධ්‍යගතකරණය", "අධිකරණ සමාලෝචනය", "රැස්වීම්, ප්‍රකාශන හා සංවාද මඟින් පුරවැසියන් දේශපාලනිකව දැනුවත් කිරීම දේශපාලන සමාජානුයෝජනයකි."),
    q("ද්විපාක්ෂික ක්‍රමයේ ප්‍රධාන වාසියක් ලෙස දේශපාලන විද්‍යාවේදී හඳුන්වා දෙන්නේ කුමක්ද?", "පැහැදිලි බහුතරයක් සහිත ස්ථාවර ආණ්ඩු බිහිවීම", "සියලු කුඩා පක්ෂ කැබිනට්ටුවට එක්වීම", "ජනමත විචාරණ අවශ්‍ය නොවීම", "අග්‍රාමාත්‍ය ධුරය අහෝසි වීම", "ප්‍රධාන පක්ෂ දෙකෙන් එකකට බහුතරය ලැබෙන බැවින් ආණ්ඩු ස්ථාවරත්වය හා වගවීම පැහැදිලිය."),
    q("බහුපාක්ෂික ක්‍රමයේ ප්‍රධාන වාසියක් ලෙස සැලකෙන්නේ කුමක්ද?", "සමාජයේ විවිධ මතවාද හා කණ්ඩායම්වලට පුළුල් නියෝජනයක් ලැබීම", "මැතිවරණ පැවැත්වීමට අවශ්‍ය නොවීම", "නිරන්තරයෙන් තනි පක්ෂ බහුතරය ලැබීම", "විපක්ෂයක් නොමැති වීම", "විවිධ ජාතික, ආර්ථික හා සමාජ අදහස් නියෝජනය කිරීමට පුරවැසියන්ට පුළුල් තේරීමක් ලැබේ."),
    q("පිළිගත් දේශපාලන පක්ෂයක් මැතිවරණ කොමිෂන් සභාවේ ලියාපදිංචි කිරීමේදී සලකා බලන ප්‍රධාන සාධකයක් කුමක්ද?", "පක්ෂ ව්‍යවස්ථාව හා අවම ක්‍රියාකාරී කාලය", "අපේක්ෂකයන්ගේ බැංකු ගිණුම් ශේෂය", "පක්ෂ නායකයාගේ උපාධි සහතිකය", "විදේශ තානාපති අනුමැතිය", "පක්ෂයේ පිළිගත් ව්‍යවස්ථාව, වාර්ෂික විගණන වාර්තා හා ප්‍රජාතන්ත්‍රවාදී ක්‍රියාකාරිත්වය පරීක්ෂා කෙරේ."),
    q("පක්ෂයක ප්‍රතිපත්ති පිළිබඳව පාර්ලිමේන්තුවේදී මන්ත්‍රීවරුන්ගේ විනය හා ඡන්ද ප්‍රකාශනය සම්බන්ධීකරණය කරන නිලධාරියා කවුද?", "පක්ෂ සංවිධායක (Whip)", "මහ ලේකම්", "දිස්ත්‍රික් ලේකම්", "කතානායක", "පාර්ලිමේන්තුවේ විවාද හා ඡන්ද විමසීම්වලදී මන්ත්‍රීවරුන්ගේ සහභාගීත්වය සංවිධානය කිරීම ආණ්ඩු හා විපක්ෂ සංවිධායකවරුන්ගේ කාර්යයයි."),
    q("මැතිවරණ කාලය තුළ රාජ්‍ය දේපළ හා රාජ්‍ය වාහන පක්ෂ ප්‍රචාරණයට යොදාගැනීම වැළැක්වීමේ බලය හිමිවන්නේ කාටද?", "මැතිවරණ කොමිෂන් සභාවට", "මුදල් අමාත්‍යාංශයට", "පළාත් සභා ලේකම්ට", "විදේශ කටයුතු අමාත්‍යවරයාට", "19 වන සංශෝධනයෙන් පසු මැතිවරණ සමයේ රාජ්‍ය දේපළ අවභාවිතය වැළැක්වීමට මැතිවරණ කොමිසමට බලය ඇත."),
    q("ජනාධිපතිවරණයකදී කිසියම් ඡන්දදායකයෙකුට පළමු මනාපය '1' නොදමා '2' පමණක් ලකුණු කළහොත් එම ඡන්දයට කුමක් වේද?", "ප්‍රතික්ෂේපිත ඡන්දයක් බවට පත්වේ", "පළමු අපේක්ෂකයාට එකතු වේ", "තෙවන වටයේදී ගණන් ගැනේ", "ජාතික ලැයිස්තුවට ගැනේ", "පළමු කැමැත්ත වන '1' හෝ කතිරය පැහැදිලිව සටහන් නොකරන ලද ඡන්ද පත්‍රිකා අවලංගු වේ."),
    q("ජනාධිපතිවරණ දෙවන වටයේදී ඉවත් කරනු ලබන අපේක්ෂකයන්ගේ ඡන්ද පත්‍රිකා පරීක්ෂා කරන්නේ කුමක් සඳහාද?", "ඉහළම අපේක්ෂකයන් දෙදෙනා වෙනුවෙන් දී ඇති දෙවන/තෙවන මනාප එකතු කිරීමට", "ඇප මුදල් ආපසු ගෙවීමට", "ප්‍රතික්ෂේපිත ඡන්ද යළි වලංගු කිරීමට", "නව පාර්ලිමේන්තු ආසන බෙදීමට", "පළමු හා දෙවන ස්ථාන ගත් අපේක්ෂකයන් දෙදෙනාට ඉවත් කළ අපේක්ෂකයන්ගේ දෙවන හෝ තෙවන මනාප මාරු කෙරේ."),
    q("ශ්‍රී ලංකාවේ පළාත් පාලන මිශ්‍ර ක්‍රමය තුළ දේශපාලන පක්ෂයකට තම මුළු සභික සංඛ්‍යාව ඉක්මවා කොට්ඨාස දිනූ විට ඇතිවන තත්ත්වය කුමක්ද?", "අතිරේක සභික ආසන (Overhang)", "ප්‍රසාද ආසන", "ජාතික ලැයිස්තු ආසන", "බහු මන්ත්‍රී ආසන", "පක්ෂයේ සමානුපාතික කෝටාවට වඩා වැඩියෙන් කොට්ඨාස දිනූ විට එම අතිරේක සභිකයන් Overhang ලෙස සභාවට එක්වේ."),
    q("දේශපාලන පක්ෂයක මූලික කාර්යභාරයට අයත් නොවන්නේ පහත සඳහන් කුමක්ද?", "අධිකරණ නඩු තීන්දු ප්‍රකාශයට පත් කිරීම", "සුදුසු දේශපාලන නායකයන් බිහි කිරීම", "මහජන අවශ්‍යතා ප්‍රතිපත්ති බවට පත් කිරීම", "රජයේ ක්‍රියා පිළිබඳ විවේචනාත්මකව බැලීම", "නඩු තීන්දු දීම ස්වාධීන අධිකරණයේ කාර්යයක් මිස දේශපාලන පක්ෂවල කාර්යයක් නොවේ."),
    q("මැතිවරණ පැවැත්වෙන දිනයේ ඡන්ද පොළේ සිට මීටර් 500ක් ඇතුළත පක්ෂ කාර්යාල පවත්වාගෙන යාම තහනම් කර ඇත්තේ ඇයි?", "ඡන්දදායකයන්ට බලපෑම් හා කලබල ඇතිවීම වැළැක්වීමට", "තැපැල් ප්‍රමාදය අඩු කිරීමට", "විදුලිය ඉතිරි කර ගැනීමට", "ගණන් කිරීමේ මධ්‍යස්ථාන පිහිටුවීමට", "ඡන්ද පොළ ආශ්‍රිත සාමය රැකීමට හා ප්‍රචාරණ බලපෑම් වැළැක්වීමට මීටර් 500 සීමාව ක්‍රියාත්මක වේ."),
    q("රටේ පාර්ලිමේන්තු මැතිවරණයකින් නව ආණ්ඩුවක් පත්වන තුරු දෛනික පරිපාලනය ගෙන යන ආණ්ඩුව කුමක්ද?", "භාරකාර රජය", "ඡායා කැබිනට්ටුව", "සභාග ආණ්ඩුව", "මහජන මන්ත්‍රණ සභාව", "මැතිවරණ සමයේ නව ප්‍රතිපත්ති තීරණ නොගෙන අත්‍යවශ්‍ය පරිපාලනය කරගෙන යන රජය භාරකාර රජයයි."),
    q("අපේක්ෂකයෙකු මැතිවරණයෙන් පසු තමා තේරී පත් වූ පක්ෂයෙන් ඉවත් වී වෙනත් පක්ෂයකට මාරු වීම හඳුන්වන්නේ කෙසේද?", "පක්ෂ මාරු කිරීම (Crossing over)", "මනාප ගණනය කිරීම", "ජෙරිමැන්ඩරින්", "විශ්වාසභංගය", "මහජන වරමට පටහැනිව මන්ත්‍රීවරුන් වෙනත් පක්ෂයකට එක්වීම පක්ෂ මාරු කිරීම ලෙස විවේචනය වේ."),
    q("1978 ව්‍යවස්ථාවේ 99(13) වගන්තිය අනුව පක්ෂයෙන් නෙරපනු ලැබූ මන්ත්‍රීවරයෙකුට අධිකරණයට යාමට ඇති අයිතිය කුමක්ද?", "මන්ත්‍රී ධුරය අහිමි කිරීමට එරෙහිව ශ්‍රේෂ්ඨාධිකරණයට පෙත්සමක් ඉදිරිපත් කිරීම", "මැතිවරණ කොමිසම විසුරුවා හැරීම", "ජනමත විචාරණයක් කැඳවීම", "පොලිස් කොමිසමට පැමිණිලි කිරීම", "මන්ත්‍රීවරයෙකු පක්ෂයෙන් නෙරපූ විට මාසයක් ඇතුළත ශ්‍රේෂ්ඨාධිකරණය හමුවේ අභියෝග කළ හැක."),
    q("සෑම පුරවැසියෙකුම මැතිවරණවලදී 'අවබෝධයෙන් යුතුව ඡන්දය භාවිත කිරීම' යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "පක්ෂ ප්‍රතිපත්ති හා අපේක්ෂක සුදුසුකම් විමසා බලා තීරණය ගැනීම", "සෑම මැතිවරණයකදීම එකම ලකුණට කතිරය ගැසීම", "තෑගි ලබාදෙන අපේක්ෂකයාට ඡන්දය දීම", "ඡන්ද පොළට නොගොස් නිවසේ රැඳී සිටීම", "පුද්ගලික ලාභ නොතකා රටට හා සමාජයට හිතකර වැඩපිළිවෙළ විමසා ඡන්දය දීම යහපත් පුරවැසි ලක්ෂණයකි."),
    q("පාර්ලිමේන්තු මැතිවරණයේදී පිළිගත් දේශපාලන පක්ෂයකට වෙනස්ව ස්වාධීන කණ්ඩායම්වලට ඡන්ද පත්‍රිකාවේ ලබාදෙන්නේ කුමක්ද?", "අංකයක් සහ විශේෂිත සලකුණක්", "පක්ෂ නායකයාගේ ඡායාරූපයක්", "ප්‍රසාද ආසනයක් කලින්ම", "වෙනම ඡන්ද පෙට්ටියක්", "මැතිවරණ කොමිසම ස්වාධීන කණ්ඩායම් සඳහා අනුක්‍රමික අංකයක් හා අනුමත ලාංඡන අතරින් සලකුණක් වෙන් කරයි."),
    q("1947 සෝල්බරි ව්‍යවස්ථාව යටතේ පැවති උත්තර මන්ත්‍රී මණ්ඩලය වූ සෙනෙට් සභාවේ අඩක් පත් කළේ කෙසේද?", "නියෝජිත මන්ත්‍රී මණ්ඩලය විසින් සමානුපාතික ඡන්දයෙන්", "මහජන සෘජු ඡන්දයෙන්", "පළාත් සභා මන්ත්‍රීවරුන් විසින්", "බ්‍රිතාන්‍ය පාර්ලිමේන්තුව විසින්", "සෙනෙට් සභිකයන් 30න් 15ක් නියෝජිත මන්ත්‍රී මණ්ඩලයෙන්ද ඉතිරි 15 අග්‍රාණ්ඩුකාරවරයා විසින්ද පත් කරන ලදී."),
    q("ශ්‍රී ලංකාවේ ඡන්ද ගණන් කිරීමේ මධ්‍යස්ථානය තුළ සිදුකරන ඡන්ද පරීක්ෂාවේදී ඡන්ද පත්‍රිකාවක නිල සලකුණ (Official Mark) නොතිබුණහොත් කුමක් වේද?", "එම ඡන්ද පත්‍රිකාව ප්‍රතික්ෂේප කෙරේ", "විපක්ෂයට හිමිවේ", "නැවත ඡන්ද පොළට යවයි", "සභාපතිවරයා අත්සන් කර වලංගු කරයි", "ඡන්ද පොළේදී පිටුපස තබන නිල රහස්‍ය මුද්‍රාව නොමැති පත්‍රිකා ව්‍යාජ ඒවා සේ සලකා ප්‍රතික්ෂේප කෙරේ."),
    q("ජාතික හා පළාත් මට්ටමින් නියෝජනය වීමට අමතරව 'ග්‍රාමීය ප්‍රජාතන්ත්‍රවාදය' පෝෂණය කරන මැතිවරණය කුමක්ද?", "පළාත් පාලන මැතිවරණය", "ජනාධිපතිවරණය", "ජනමත විචාරණය", "සෙනෙට් මැතිවරණය", "මහ නගර සභා, නගර සභා හා ප්‍රාදේශීය සභා මැතිවරණ මඟින් ගම හා නගර මට්ටමේ නායකයන් බිහිවේ."),
    q("විධිමත් දේශපාලන පක්ෂ ක්‍රමයක් නොමැති වුවහොත් පාර්ලිමේන්තු ප්‍රජාතන්ත්‍රවාදයේ ඇතිවිය හැකි ප්‍රධාන ගැටලුව කුමක්ද?", "ස්ථාවර ප්‍රතිපත්තියක් හා සංවිධානාත්මක විපක්ෂයක් නොමැති වීම", "ඡන්දදායකයන් ඡන්ද පොළට යාම වැඩි වීම", "නීති සම්පාදනය ඉතා වේගවත් වීම", "මැතිවරණ කොමිසම අනවශ්‍ය වීම", "පක්ෂ නොමැති විට ස්වාධීන මන්ත්‍රීන් අතර ස්ථාවර ආණ්ඩුවක් හා වගවීමක් පවත්වාගැනීම දුෂ්කර වේ."),
    q("මැතිවරණ ප්‍රතිඵල ප්‍රකාශයට පත්කිරීමෙන් පසු පාර්ලිමේන්තු මන්ත්‍රීවරුන්ගේ නම් රජයේ ගැසට් පත්‍රයේ පළ කරන්නේ කවුද?", "මැතිවරණ කොමිෂන් සභාව", "පාර්ලිමේන්තු කතානායකවරයා", "අධිකරණ අමාත්‍යාංශය", "රජයේ මුද්‍රණාලයාධිපති තනිව", "තේරී පත් වූ හා ජාතික ලැයිස්තු මන්ත්‍රීවරුන්ගේ නම් මැතිවරණ කොමිසම මඟින් ගැසට් මඟින් ප්‍රකාශයට පත් කරයි."),
    q("පළාත් පාලන මැතිවරණ නීතියේ කොට්ඨාස ක්‍රමය යළි හඳුන්වා දීමෙන් අපේක්ෂා කළ ප්‍රධානම අරමුණ කුමක්ද?", "සෑම ගමකටම හා කොට්ඨාසයකටම වගකියන සභිකයෙකු පත් කිරීම", "මන්ත්‍රීවරුන් සංඛ්‍යාව දහයකට අඩු කිරීම", "මැතිවරණ කොමිසම අහෝසි කිරීම", "තැපැල් ඡන්දය නතර කිරීම", "සමානුපාතික ක්‍රමයේ තිබූ කොට්ඨාස නියෝජිත හිඟය මඟහරවා ගමට වගකියන සභිකයන් බිහි කිරීම මෙහි අරමුණයි."),
    q("ජනාධිපතිවරණයකදී අපේක්ෂකයෙකු ලැබූ වලංගු ඡන්ද ප්‍රමාණය 5%ට වඩා අඩු වුවහොත් (පිළිගත් පක්ෂයක නම්) ඇප මුදලට කුමක් වේද?", "ඇප මුදල රාජසන්තක වේ", "ඇප මුදල දෙගුණ කර ආපසු දේ", "දෙවන වටයේ ඡන්දයකට සුදුසුකම් ලබයි", "ජාතික ලැයිස්තු ආසනයක් හිමිවේ", "නියමිත 5% ඡන්ද සීමාව නොඉක්මවන ජනාධිපති අපේක්ෂකයාගේ ඇප මුදල රජයට අයත් වේ."),
    q("නියෝජිත ප්‍රජාතන්ත්‍රවාදයේදී 'ජනමත විචාරණයක්' වැදගත් වන්නේ මන්ද?", "ප්‍රධාන ජාතික තීරණවලදී ජනතාවට සෘජුවම අදහස් පළ කිරීමට අවස්ථාව දෙන බැවිනි", "රජයේ බදු පොලී අනුපාතය දිනපතා වෙනස් කිරීමට", "අධිකරණ නඩු කඩිනමින් විසඳීමට", "රාජ්‍ය සේවක වැටුප් ගෙවීමට", "ව්‍යවස්ථාවේ මූලික අංග වෙනස් කිරීම වැනි තීරණාත්මක අවස්ථාවලදී ජනතා පරමාධිපත්‍යය සෘජුව ප්‍රකාශ වේ."),
    q("මැතිවරණයකට තරග කරන පක්ෂ හා අපේක්ෂකයන් අතර මැතිවරණ කොමිසම මඟින් සම අවස්ථා සලසා දෙන ක්ෂේත්‍රයක් කුමක්ද?", "රාජ්‍ය විද්‍යුත් හා මුද්‍රිත මාධ්‍ය ගුවන් කාලය", "පුද්ගලික ව්‍යාපාර ආදායම", "පවුල් දේපළ බෙදීම", "අධිකරණ විනිසුරු පත්වීම්", "මැතිවරණ කාලසීමාවේදී රාජ්‍ය මාධ්‍ය ආයතන තුළ සියලු පක්ෂවලට සාධාරණ ගුවන් කාලයක් වෙන් කළ යුතුය."),
    q("පළමුව තෝරා ගැනුණු පළාත් සභා හෝ පාර්ලිමේන්තු මන්ත්‍රීවරයෙකු අධිකරණයකින් බරපතළ අපරාධ වරදකට වැරදිකරු වී සිරදඬුවම් නියම වුවහොත් කුමක් සිදුවේද?", "මන්ත්‍රී ධුරය අහිමි වේ", "විපක්ෂ නායක ධුරය හිමිවේ", "ප්‍රසාද ආසනයක් ලැබේ", "ධුර කාලය වසර දහයකින් දිගු වේ", "ව්‍යවස්ථාවේ 89 හා 91 වගන්ති අනුව අධිකරණ තීන්දුවකින් නුසුදුසුකමට ලක් වූ විට මන්ත්‍රී ධුරය හිස් වේ."),
    q("සරල බහුතර ක්‍රමයේදී අපේක්ෂකයන් ගණන වැඩිවන විට ඡන්ද බෙදී ගොස් 30% වැනි අඩු ප්‍රතිශතයකින් පවා ජයග්‍රහණය කළ හැකි වීම හඳුන්වන්නේ කෙසේද?", "සුළුතර ඡන්දයෙන් තේරී පත්වීම", "නිරපේක්ෂ බහුතර ජයග්‍රහණය", "සමානුපාතික සම්මුතිය", "ඒකමතික ජයග්‍රහණය", "වැඩි ඡන්ද පිරිසක් පරාජිත අපේක්ෂකයන් අතර බෙදී යාමෙන් බහුතර ජනතාව අකමැති අයෙකු දිනීමේ අවදානම පවතී."),
    q("බලපෑම් කණ්ඩායම් සහ දේශපාලන පක්ෂ අතර ඇති සමානකම කුමක්ද?", "රාජ්‍ය ප්‍රතිපත්ති සම්පාදනය කෙරෙහි බලපෑම් කිරීම", "රාජ්‍ය ආණ්ඩු බලය ලබාගැනීමට තරග කිරීම", "මැතිවරණ පැවැත්වීමේ නීතිමය බලය දැරීම", "ශ්‍රේෂ්ඨාධිකරණ තීන්දු වෙනස් කිරීම", "පක්ෂ මෙන්ම වෘත්තීය සමිති හා සිවිල් සංවිධානද මහජන මතය ගොඩනඟා රාජ්‍ය ප්‍රතිපත්ති හැඩගස්වයි."),
    q("ශ්‍රී ලංකාවේ ප්‍රථම වරට තරග කළ හැකි හා ඡන්දය දිය හැකි වයස අවුරුදු 18 බවට පත් කළ පසු පැවැත්වූ පළමු මහ මැතිවරණය පැවැත්වුණේ කුමන වර්ෂයේදීද?", "1960 මාර්තු", "1956 අප්‍රේල්", "1947 අගෝස්තු", "1977 ජූලි", "1959 දී වයස 18 දක්වා අඩු කිරීමෙන් පසු 1960 මාර්තු මහ මැතිවරණයේදී තරුණ ඡන්දදායකයන් ප්‍රථම වරට ඡන්දය දුන්හ."),
    q("ඡන්ද පොළකදී ආබාධිත හෝ දෘශ්‍යාබාධිත ඡන්දදායකයෙකුට ඡන්දය ප්‍රකාශ කිරීමට සලසා ඇති විශේෂ පහසුකම කුමක්ද?", "සහකාර පුද්ගලයෙකු හෝ ස්ථානාධිපතිගේ සහාය ලබාගැනීම", "තැපැල් ඡන්දයෙන් පසුව ඡන්දය දීම", "ඡන්ද පොළෙන් පිටත සිට ඡන්දය දීම", "දිස්ත්‍රික් ලේකම්ගේ කැමැත්තෙන් කතිරය නොගැසීම", "සුදුසුකම් සහතිකයක් සහිත සහායකයෙකු හෝ නියෝජිතයන් ඉදිරියේ ස්ථානාධිපතිගේ සහාය ඇතිව ඡන්දය දිය හැක."),
    q("දේශපාලන පක්ෂයක අභ්‍යන්තර ප්‍රජාතන්ත්‍රවාදය යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "පක්ෂ නායකත්වය හා ප්‍රතිපත්ති පක්ෂ සාමාජික ඡන්දයෙන් හා සාකච්ඡාවෙන් තීරණය වීම", "පක්ෂයේ සියලු දෙනා එක් අයෙකුට පමණක් අවනත වීම", "පක්ෂයේ ගිණුම් රහසිගතව තැබීම", "නායකත්වය පරම්පරාවෙන් පමණක් උරුම වීම", "පක්ෂ තුළ නිලවරණ, අදහස් පළ කිරීමේ නිදහස හා වගවීම තිබීම අභ්‍යන්තර ප්‍රජාතන්ත්‍රවාදයයි."),
    q("මැතිවරණයකින් පසු පරාජිත පක්ෂය සාමකාමීව බලය අත්හැර ජයග්‍රාහී පක්ෂයට රජය භාරදීම පිළිබිඹු කරන්නේ කුමක්ද?", "ප්‍රජාතන්ත්‍රවාදී දේශපාලන සංස්කෘතිය", "ඒකාධිපති පාලන ව්‍යුහය", "හමුදා ආඥාදායකත්වය", "රාජාණ්ඩු සම්ප්‍රදාය", "ඡන්ද ප්‍රතිඵලයට ගරු කරමින් ප්‍රචණ්ඩත්වයෙන් තොරව බලය හුවමාරු කිරීම ප්‍රජාතන්ත්‍රවාදයේ පරිණත ලක්ෂණයකි."),
    q("1978 ව්‍යවස්ථාව යටතේ ජනාධිපති ධුරය හිස් වූ අවස්ථාවක පාර්ලිමේන්තුව මඟින් ජනාධිපතිවරයෙකු තෝරාගත් ප්‍රථම අවස්ථාව සිදුවූයේ කවදාද?", "1993", "1982", "1989", "2010", "1993 මැයි මාසයේදී ආර්. ප්‍රේමදාස ජනාධිපතිවරයාගේ අභාවයෙන් පසු ඩී.බී. විජේතුංග මහතා පාර්ලිමේන්තුවෙන් පත්විය."),
    q("වැඩිම ඡන්ද ගත් පක්ෂයට ප්‍රසාද ආසනය ලබාදීමේ මූලික අරමුණ කුමක් වීද?", "දිස්ත්‍රික්කය ජයගත් පක්ෂයට ස්ථාවර ආසන වාසියක් ලබාදීම", "පැරදුණු පක්ෂවලට අමතර ආසන දීම", "ජාතික ලැයිස්තු ආසන අහෝසි කිරීම", "මැතිවරණ කොමිසමේ වියදම් අඩු කිරීම", "සමානුපාතික ක්‍රමයේදී පාලක පක්ෂයට පාර්ලිමේන්තුවේ ක්‍රියාකාරී බහුතරයක් ගොඩනැගීම පහසු කිරීමට ප්‍රසාද ආසනය එක් කෙරිණි."),
    q("පක්ෂයක මූල්‍ය විනිවිදභාවය සහ මැතිවරණ දූෂණ අවම කිරීමට වඩාත්ම උපකාරී වන පියවර කුමක්ද?", "ප්‍රචාරණ වියදම් සීමා කිරීම හා ආදායම් මූලාශ්‍ර විගණනය කිරීම", "ඡන්දදායක වයස අවුරුදු 30 දක්වා වැඩි කිරීම", "රහස් ඡන්ද ක්‍රමය අහෝසි කිරීම", "විපක්ෂ රැස්වීම් තහනම් කිරීම", "මැතිවරණ අරමුදල් හා වියදම් නීත්‍යානුකූලව නිරීක්ෂණය කිරීමෙන් ධන බලයේ අනිසි බලපෑම පාලනය කළ හැක."),
    q("නියෝජිත ප්‍රජාතන්ත්‍රවාදයේදී දේශපාලන පක්ෂ 'මහජනතාව සහ රජය අතර පාලමක්' ලෙස ක්‍රියා කරන්නේ කෙසේද?", "මහජන අදහස් එක්රැස් කර රජයේ ප්‍රතිපත්ති බවට පත් කිරීමෙන්", "පොලිස් බලතල ක්‍රියාත්මක කිරීමෙන්", "බදු අය කිරීමේ නිලධාරීන් පත් කිරීමෙන්", "අධිකරණ නඩු විභාග කිරීමෙන්", "පුරවැසියන්ගේ අපේක්ෂා හා ගැටලු පාර්ලිමේන්තුව වෙත ගෙන යාම දේශපාලන පක්ෂවල ප්‍රධාන කාර්යයකි."),
    q("ශ්‍රී ලංකාවේ පාර්ලිමේන්තු මැතිවරණයකදී කිසියම් දිස්ත්‍රික්කයක 5% සීමාව ඉක්මවීමට කිසිදු පක්ෂයක් හෝ එක් පක්ෂයක් පමණක් සමත් වුවහොත් සිදුවන්නේ කුමක්ද?", "5% ඉක්මවූ පක්ෂයට හෝ පක්ෂවලට පමණක් දිස්ත්‍රික් ආසන බෙදී යයි", "මැතිවරණය අවලංගු කර ජනාධිපති පාලනය පැනවේ", "සියලු ආසන ජාතික ලැයිස්තුවට එකතු වේ", "ප්‍රසාද ආසනය කතානායකට හිමිවේ", "5% අවම සීමාව නොඉක්මවන පක්ෂවල ඡන්ද ඉවත් කර ඉක්මවූ පක්ෂ අතර පමණක් ආසන බෙදා දෙනු ලැබේ."),
    q("ඡන්දදායකයන් ඡන්දය ප්‍රකාශ නොකර සිටීම (Low Voter Turnout) ප්‍රජාතන්ත්‍රවාදයට අහිතකර වන්නේ ඇයි?", "තේරී පත්වන ආණ්ඩුවට සමස්ත ජනතාවගේ පුළුල් වරමක් නොලැබෙන බැවිනි", "ඡන්ද පත්‍රිකා මුද්‍රණ වියදම වැඩි වන බැවිනි", "ජාතික ලැයිස්තු ආසන අඩු වන බැවිනි", "ව්‍යවස්ථා සංශෝධන අවශ්‍ය නොවන බැවිනි", "අඩු ඡන්ද ප්‍රතිශතයකින් පත්වන ආණ්ඩුවල ජනතා නියෝජනය හා ප්‍රජාතන්ත්‍රවාදී සුජාතභාවය දුර්වල වේ."),
    q("පක්ෂ ප්‍රතිපත්ති ප්‍රකාශනයක් සම්පාදනය කිරීමේදී පක්ෂයක් අවධානය යොමු කළ යුතු ප්‍රධාන කරුණ කුමක්ද?", "රටේ ආර්ථික ශක්තියට ගැළපෙන ප්‍රායෝගික විසඳුම් ඉදිරිපත් කිරීම", "ප්‍රතිවාදී පක්ෂ තහනම් කිරීමේ පොරොන්දු දීම", "රාජ්‍ය සේවය සම්පූර්ණයෙන් වසා දැමීම", "අධිකරණ තීන්දු ප්‍රතික්ෂේප කිරීම", "ඉටු කළ හැකි යථාර්ථවාදී ආර්ථික, අධ්‍යාපන හා සමාජ වැඩපිළිවෙළක් ජනතාවට ඉදිරිපත් කළ යුතුය."),
    q("මැතිවරණ දිස්ත්‍රික්ක 22 අතරින් වර්තමානයේ අඩුම පාර්ලිමේන්තු ආසන සංඛ්‍යාවක් වෙන් කර ඇති දිස්ත්‍රික්කයක් කුමක්ද?", "ත්‍රිකුණාමලය හෝ මඩකලපුව", "කොළඹ හෝ ගම්පහ", "කුරුණෑගල හෝ මහනුවර", "ගාල්ල හෝ රත්නපුර", "අඩු ජනගහනයක් ඇති ත්‍රිකුණාමලය (ආසන 4) වැනි දිස්ත්‍රික්කවලට කොළඹට හා ගම්පහට වඩා අඩු ආසන වෙන්වේ."),
    q("ඡන්ද පොළකදී ඡන්දදායකයෙකුට වැරදීමකින් ඡන්ද පත්‍රිකාව ඉරුණහොත් හෝ වැරදි ස්ථානයක ලකුණු කළහොත් කළ හැක්කේ කුමක්ද?", "පෙට්ටියට නොදමා ස්ථානාධිපතිට දී අලුත් පත්‍රිකාවක් ඉල්ලා සිටීම", "පෑනෙන් කපා නිවැරදි කර පෙට්ටියට දැමීම", "පිටුපස කතිරය ගසා පෙට්ටියට දැමීම", "දෙවන වරට පෝලිමට ගොස් ගැනීම", "පෙට්ටියට දැමීමට පෙර ඡන්ද ස්ථානාධිපතිට භාර දී එය අවලංගු කර නව ඡන්ද පත්‍රිකාවක් ලබාගත හැක."),
    q("ශ්‍රී ලංකාවේ පළාත් පාලන මැතිවරණ පනත යටතේ කාන්තා නියෝජනය 25% තහවුරු කිරීම සිදුකරන්නේ කෙසේද?", "සමානුපාතික හා කොට්ඨාස ලැයිස්තු දෙකෙහිම කාන්තා කෝටා අනිවාර්ය කිරීමෙන්", "පිරිමින්ට ඡන්දය දීම තහනම් කිරීමෙන්", "කාන්තාවන්ට ද්විත්ව ඡන්දයක් දීමෙන්", "වෙනම කාන්තා පාර්ලිමේන්තුවක් පිහිටුවීමෙන්", "නාමයෝජනා පත්‍රවල කොට්ඨාස හා අතිරේක ලැයිස්තු දෙකෙහිම නියමිත කාන්තා ප්‍රතිශතය ඇතුළත් කිරීම අනිවාර්ය වේ."),
    q("පක්ෂ ලැයිස්තුවක 'සංවෘත ලැයිස්තු' ක්‍රමය යොදාගැනීමෙන් ලැබෙන ප්‍රධාන වාසිය කුමක්ද?", "එකම පක්ෂයේ අපේක්ෂකයන් අතර මනාප ගැටුම් නැතිවීම", "ඡන්දදායකයන්ට අපේක්ෂකයා මාරු කිරීමට හැකි වීම", "මැතිවරණ දිස්ත්‍රික්ක සංඛ්‍යාව වැඩි වීම", "අතුරු මැතිවරණ වැඩි වීම", "මනාප අංක සටනක් නොමැති බැවින් අභ්‍යන්තර ගැටුම් හා ප්‍රචාරණ වියදම් අඩු වී විද්වතුන්ට ඉඩ ලැබේ."),
    q("විදේශීය හෝ දේශීය මැතිවරණ නිරීක්ෂකයන්ට ඡන්ද පොළ තුළ ඉටු කළ හැකි කාර්යභාරය කුමක්ද?", "ඡන්ද විමසීමේ නීත්‍යානුකූල හා සාධාරණ බව නිරීක්ෂණය කර වාර්තා කිරීම", "ඡන්ද පත්‍රිකාවල කතිරය ගැසීම", "අපේක්ෂකයන් ඉවත් කිරීම", "ඡන්ද ගණන් කිරීම තනිවම කිරීම", "මැතිවරණ කොමිසමේ අවසරයෙන් පැමිණෙන නිරීක්ෂකයන් ඡන්ද ක්‍රියාවලියේ විනිවිදභාවය ස්වාධීනව වාර්තා කරයි."),
    q("මැතිවරණ කොට්ඨාසයක් සඳහා 'බහු මන්ත්‍රී ආසනයක්' පිහිටුවීමේ ප්‍රධාන ප්‍රජාතන්ත්‍රවාදී අරමුණ කුමක් වීද?", "සුළු ජන කොටස්වලටද එම කොට්ඨාසයෙන් නියෝජනයක් ලබාදීම", "එක් අපේක්ෂකයෙකුට ඡන්ද තුනක් දීම", "මැතිවරණ කොමිසම විසුරුවා හැරීම", "ජනමත විචාරණ පැවැත්වීම", "බහු වාර්ගික හෝ බහු ආගමික ප්‍රදේශවල සුළුතර කණ්ඩායම්වලට මන්ත්‍රී ධුරයක් හිමිවීමට ඉඩ සැලසීම මෙහි අරමුණයි."),
    q("ඡන්දදායකයන් වෙත 'අපේක්ෂකයන්ගේ වත්කම් බැරකම් ප්‍රකාශ හෙළිදරව් කිරීම' වැදගත් වන්නේ ඇයි?", "පාරදෘශ්‍යභාවය ඇති කර දූෂිත පාලනය වැළැක්වීමට", "රජයේ බදු අඩු කිරීමට", "තැපැල් සේවාව දියුණු කිරීමට", "මැතිවරණ දිනය කල් දැමීමට", "දේශපාලන නියෝජිතයන්ගේ ආර්ථික විනිවිදභාවය දැනගැනීමෙන් බුද්ධිමත් ඡන්ද තීරණයක් ගැනීමට ජනතාවට හැකිවේ."),
    q("මහ මැතිවරණයකින් පසු ජාතික ලැයිස්තු මන්ත්‍රී ධුරයක පුරප්පාඩුවක් ඇති වුවහොත් එය පුරවන්නේ කෙසේද?", "අදාළ පක්ෂයේ මහ ලේකම්වරයාගේ නාමකරණයෙන්", "එම දිස්ත්‍රික්කයේ අතුරු මැතිවරණයකින්", "ජනමත විචාරණයකින්", "ශ්‍රේෂ්ඨාධිකරණ විනිසුරු මණ්ඩලයෙන්", "ජාතික ලැයිස්තු පුරප්පාඩුවක් සඳහා අදාළ දේශපාලන පක්ෂයේ මහ ලේකම් විසින් සුදුසු නමක් නම් කර එවනු ලැබේ."),
    q("1982 ජනමත විචාරණයෙන් පසු ශ්‍රී ලංකාවේ දේශපාලන විචාරකයන් එය විවේචනය කිරීමට ප්‍රධාන හේතුව කුමක්ද?", "ප්‍රජාතන්ත්‍රවාදී මහ මැතිවරණයකට තිබූ අවස්ථාව වසර හයකින් කල් යාම", "ඡන්ද වයස අවුරුදු 25 දක්වා වැඩි කිරීම", "සර්වජන ඡන්ද බලය අහෝසි කිරීම", "පළාත් සභා නවයක් එක් කිරීම", "නියමිත 1983 මහ මැතිවරණය නොපවත්වා පාර්ලිමේන්තු කාලය දිගු කිරීම බහුපාක්ෂික නියෝජනයට බාධාවක් ලෙස සැලකුණි."),
    q("සෘජු හා වක්‍ර මැතිවරණ ක්‍රම අතරින් මහජන කැමැත්ත වඩාත් පැහැදිලිව නිරූපණය වන ක්‍රමය කුමක්ද?", "සෘජු මැතිවරණ ක්‍රමය", "වක්‍ර මැතිවරණ ක්‍රමය", "රාජකීය පත්වීම් ක්‍රමය", "ඒකපාක්ෂික නාමකරණ ක්‍රමය", "මහජනතාව කිසිදු අතරමැදියෙකු නොමැතිව සෘජුවම තම නියෝජිතයන්ට ඡන්දය දෙන බැවින් සෘජු ක්‍රමය වඩාත් ප්‍රජාතන්ත්‍රවාදී වේ."),
    q("ශ්‍රී ලංකාවේ ඡන්ද හිමි නාමලේඛනයට පුරවැසියෙකුගේ නම ඇතුළත් කිරීම සඳහා සාමාන්‍යයෙන් සලකා බලන මූලික නිර්ණායකය කුමක්ද?", "අදාළ ලිපිනයේ සාමාන්‍ය පදිංචිය", "මාසික බැංකු ආදායම", "උසස් පෙළ සමත් වීම", "රජයේ රැකියාවක් තිබීම", "වයස 18 සපිරීම හා පුරවැසිභාවය සමඟ අදාළ ග්‍රාම නිලධාරී වසමේ සාමාන්‍ය පදිංචිය තහවුරු විය යුතුය."),
    q("ප්‍රජාතන්ත්‍රවාදී රාජ්‍යයක 'මැතිවරණ චක්‍රය' නිතිපතා නියමිත කාලයට පැවැත්වීමෙන් සිදුවන්නේ කුමක්ද?", "පාලකයන්ගේ වගවීම තහවුරු වීම හා ජනතා විරෝධය සාමකාමීව ප්‍රකාශ වීම", "රජයේ සියලු පනත් අහෝසි වීම", "අධිකරණ පද්ධතිය වෙනස් වීම", "ආණ්ඩුක්‍රම ව්‍යවස්ථාව සෑම වසරකම ලිවීම", "නිශ්චිත කාලසීමාවකට වරක් මහජන විනිශ්චයට මුහුණ දීමට සිදුවීමෙන් පාලකයෝ ජනතාවට වගකිව යුතු වෙති."),
    q("ශ්‍රී ලංකාවේ 'තැපැල් ඡන්ද පහසුකම' (Postal Voting) හිමිවන්නේ කුමන ඡන්දදායක කණ්ඩායමකටද?", "මැතිවරණ රාජකාරිවල නිරත රාජ්‍ය සේවකයන්, ගුරුවරුන්, පොලිසිය හා ත්‍රිවිධ හමුදා සාමාජිකයන්", "විදේශගත සංචාරකයන්ට පමණි", "වයස 18ට අඩු පාසල් සිසුන්ට", "පෞද්ගලික වෙළඳසැල් හිමියන්ට", "මැතිවරණ දිනයේදී රාජකාරි නිසා තම ඡන්ද මධ්‍යස්ථානයට යා නොහැකි නිලධාරීන්ට කලින් ඡන්දය දීමට ඉන් ඉඩ සැලසේ."),
    q("මැතිවරණයකදී අපේක්ෂකයෙකුට හෝ දේශපාලන පක්ෂයකට ලැබෙන ඡන්ද ප්‍රමාණය නියමිත 'ඇප මුදල රාජසන්තක නොවීමට' නම් කළ යුත්තේ කුමක්ද?", "නීතියෙන් නියම කළ අවම වලංගු ඡන්ද ප්‍රතිශතය හෝ ප්‍රමාණය ලබාගැනීම", "පුවත්පත්වල දැන්වීම් පළ කිරීම", "ඡන්ද පෙට්ටි ගණන් කිරීමට පෙර පිටව යාම", "මැතිවරණ කොමිසමට ලිපියක් යැවීම", "අනවශ්‍ය ලෙස අපේක්ෂකයන් ඉදිරිපත් වී ඡන්ද පත්‍රිකාව දිගු වීම වැළැක්වීමට ඇප තැන්පත් ක්‍රමය භාවිත කෙරේ."),
    q("ශ්‍රී ලංකාවේ 1988 වසරේ 14 වන ආණ්ඩුක්‍රම ව්‍යවස්ථා සංශෝධනයෙන් පාර්ලිමේන්තු මැතිවරණ සඳහා සිදු කළ වැදගත් වෙනස්කම් දෙක කුමක්ද?", "ප්‍රසාද ආසන ක්‍රමය හඳුන්වා දීම හා පක්ෂයකට ආසන ලබාගැනීමේ අවම සීමාව (Cut-off point) 12.5% සිට 5% දක්වා අඩු කිරීම", "සර්වජන ඡන්ද බලය අහෝසි කිරීම", "මන්ත්‍රී සංඛ්‍යාව 100 දක්වා අඩු කිරීම", "ජනාධිපති ධුරය අහෝසි කිරීම", "කුඩා හා සුළුතර දේශපාලන පක්ෂවලටද පාර්ලිමේන්තු නියෝජනය ලබාගැනීමට 5% සීමාව පහසු කළේය."),
    q("මැතිවරණ ප්‍රචාරක කටයුතුවලදී 'නිහඬ කාලසීමාව' (Silence Period - ඡන්ද විමසීමට පැය 48කට පෙර) පනවනු ලබන්නේ ඇයි?", "පක්ෂ ප්‍රචාරක ඝෝෂාවලින් තොරව නිදහසේ සිතා ඡන්ද තීරණය ගැනීමට ඡන්දදායකයාට ඉඩ දීමට", "ඡන්ද පොළවල් වසා දැමීමට", "අපේක්ෂකයන් සිරගත කිරීමට", "තැපැල් ඡන්ද අවලංගු කිරීමට", "මැතිවරණ පනත අනුව ඡන්දයට පැය 48කට පෙර ප්‍රචාරක රැස්වීම්, පෝස්ටර් හා ප්‍රචාර නතර කළ යුතුය."),
    q("2023 අංක 3 දරන මැතිවරණ වියදම් නියාමන පනත මඟින් ප්‍රජාතන්ත්‍රවාදයට ලැබුණු ප්‍රධාන ශක්තිය කුමක්ද?", "අපේක්ෂකයන්ගේ හා පක්ෂවල ප්‍රචාරක වියදම්වලට නීතිමය උපරිම සීමාවක් පනවා මුදල් බලය පාලනය කිරීම", "ඡන්දදායකයන්ට මුදල් බෙදාදීම නීත්‍යානුකූල කිරීම", "මැතිවරණ කොමිසමේ බලතල අඩු කිරීම", "ජාතික ලැයිස්තුව අහෝසි කිරීම", "ධනවත් හා දූෂිත මුදල් මගින් මැතිවරණ ප්‍රතිඵලය මිලදී ගැනීම වැළැක්වීම මෙහි අරමුණයි."),
    q("මැතිවරණ කොමිෂන් සභාව විසින් නිකුත් කරන 'ඡන්ද දැන්වීම් පත්‍රිකාව' (Poll Card) ගෙන යාමෙන් ඡන්දදායකයාට ලැබෙන පහසුව කුමක්ද?", "තම ඡන්ද මධ්‍යස්ථානය හා ඡන්ද හිමි නාමලේඛන අනුක්‍රමික අංකය පහසුවෙන් හඳුනාගැනීම", "හැඳුනුම්පත නොමැතිව ඡන්දය දීමට හැකි වීම", "දෙවරක් ඡන්දය ප්‍රකාශ කිරීමට හැකි වීම", "තැපැල් ගාස්තු අඩු වීම", "ඡන්ද කාඩ්පත අනිවාර්ය නොවූවත් වලංගු හැඳුනුම්පතක් (NIC, ගමන් බලපත්‍රය, රියදුරු බලපත්‍රය) සමඟ ගිය විට ක්‍රියාවලිය ඉක්මන් වේ."),
    q("ඡන්ද විමසීමකදී ඡන්දදායකයාගේ 'වම් අතේ සුළැඟිල්ලේ නොමැකෙන තීන්ත' ආලේප කරන්නේ කුමන වංචාවක් වැළැක්වීමටද?", "එකම පුද්ගලයෙකු එක් මැතිවරණයකදී දෙවරක් හෝ වෙනත් අයෙකු ලෙස පෙනී සිට ඡන්දය දීම (Impersonation)", "ඡන්ද පත්‍රිකාව ඉරී යාම", "මනාප ගණන් කිරීමේ ප්‍රමාදය", "නාමයෝජනා ප්‍රතික්ෂේප වීම", "නිදහස් හා සාධාරණ මැතිවරණයක 'එක් අයෙකුට එක් ඡන්දයක්' යන නීතිය ඉන් සුරැකේ."),
    q("බහුපක්ෂ ප්‍රජාතන්ත්‍රවාදී ක්‍රමයක 'විරුද්ධ පක්ෂය' (Parliamentary Opposition) ඉටු කරන අත්‍යවශ්‍ය ප්‍රජාතන්ත්‍රවාදී කාර්යභාරය කුමක්ද?", "ආණ්ඩුවේ වැරදි හා අඩුපාඩු විවේචනය කරමින් ජනතාවට විකල්ප ප්‍රතිපත්ති හා ආණ්ඩුවක් ඉදිරිපත් කිරීම", "පාර්ලිමේන්තු රැස්වීම් කඩාකප්පල් කිරීම පමණි", "රජයේ අයවැය විවාද වර්ජනය කිරීම", "ඡන්දදායකයන් තහනම් කිරීම", "වගවීම ඇති කිරීමට හා ඒකාධිපතිත්වය වැළැක්වීමට ශක්තිමත් විපක්ෂයක් රජයක සමබරතාව රකී."),
    q("රටේ පාර්ලිමේන්තු හෝ ජනාධිපති මැතිවරණ පැවැත්වෙන කාලයේදී රාජ්‍ය දේපළ (රජයේ වාහන, ගොඩනැගිලි, රාජ්‍ය මාධ්‍ය) අපේක්ෂකයන්ට භාවිත කළ නොහැක්කේ ඇයි?", "සියලු අපේක්ෂකයන්ට සමාන තරග බිමක් (Level Playing Field) ලබාදී මහජන මුදල් අවභාවිතය වැළැක්වීමට", "රජයේ වාහන ධාවනය නොවන බැවින්", "මැතිවරණ නිරීක්ෂකයන් නැති නිසා", "ජනමාධ්‍ය වසා තබන නිසා", "ආණ්ඩුක්‍රම ව්‍යවස්ථාවේ 104ඌ වගන්තිය යටතේ රාජ්‍ය සම්පත් මැතිවරණ ප්‍රචාරණයට යොදාගැනීම මැතිවරණ කොමිසමට තහනම් කළ හැක."),
    q("ශ්‍රී ලංකාවේ දේශපාලන පක්ෂයක් මැතිවරණ කොමිෂන් සභාවේ 'පිළිගත් දේශපාලන පක්ෂයක්' ලෙස ලියාපදිංචි වීමෙන් ලැබෙන ප්‍රධාන වාසිය කුමක්ද?", "වෙන් කරන ලද ස්ථිර පක්ෂ ලකුණක් යටතේ අඩු ඇප මුදලකින් මැතිවරණවලට තරග කිරීමට හැකි වීම", "සෑම පුරවැසියෙකුගෙන්ම බදු අය කිරීමට හැකි වීම", "විනිසුරුවරුන් පත් කිරීමේ බලය", "මුදල් අච්චු ගැසීමේ බලය", "පක්ෂ ව්‍යවස්ථාව, වාර්ෂික විගණිත ගිණුම් හා අවම වසර ගණනක ක්‍රියාකාරිත්වය සැලකිල්ලට ගෙන ලියාපදිංචි කෙරේ."),
    q("මැතිවරණ ප්‍රතිඵලයක් සම්බන්ධයෙන් නීතිමය දූෂණ හෝ අක්‍රමිකතා චෝදනාවක් ඇති විට පරාජිත අපේක්ෂකයෙකුට ගත හැකි නීතිමය පියවර කුමක්ද?", "අභියාචනාධිකරණය හෝ ශ්‍රේෂ්ඨාධිකරණය වෙත 'මැතිවරණ පෙත්සමක්' (Election Petition) ගොනු කිරීම", "ප්‍රතිඵල නිවේදනය කළ නිලධාරියාට දඩ ගැසීම", "සමථ මණ්ඩලයට යාම", "නව මැතිවරණ කොමිසමක් පත් කිරීම", "ඡන්ද මංකොල්ල හෝ අල්ලස් ඔප්පු වුවහොත් අධිකරණයට අදාළ මන්ත්‍රීවරයාගේ තේරී පත්වීම අවලංගු කළ හැක.")
  )
}

